    BarCount? barCount,
    SpectrumColorScheme? colorScheme,
    BarStyle? barStyle,
    DecaySpeed? decaySpeed,
  }) =>
      SpectrumSettings(
        noiseGateDb: noiseGateDb ?? this.noiseGateDb,
        barCount: barCount ?? this.barCount,
